// Generated from the vendored Lucide SVGs in `assets/lucide/` (see
// `assets/lucide/README.md`) by `assets/lucide/generate.py`. Do not edit.

use super::*;

/// The path segments that draw `icon` on the 24x24 Lucide grid.
